#include <set>
#include <string>
#include <vector>

struct Machine
{
    std::string appDir;
    std::string currentDir;
    std::vector<std::string> pathDirs;
    std::set<std::string> files;
    std::set<std::string> knownDlls;
    std::set<std::string> alreadyLoaded;
};

std::string findDll(const Machine& m, const std::string& name)
{
    const std::string suffix{ "\\" + name };
    for (const std::string& loaded : m.alreadyLoaded)
        if (loaded.size() >= suffix.size() && loaded.compare(loaded.size() - suffix.size(), suffix.size(), suffix) == 0) return loaded;
    if (m.knownDlls.count(name)) return "C:\\Windows\\System32\\" + name;
    std::vector<std::string> folders{ m.appDir, "C:\\Windows\\System32", "C:\\Windows\\System", "C:\\Windows", m.currentDir };
    folders.insert(folders.end(), m.pathDirs.begin(), m.pathDirs.end());
    for (const std::string& folder : folders)
    {
        const std::string candidate{ folder + "\\" + name };
        if (m.files.count(candidate)) return candidate;
    }
    return "";
}

unitTests:
Machine sample() {
    Machine m;
    m.appDir = "C:\\Games\\Xenon"; m.currentDir = "C:\\Users\\ada\\Desktop"; m.pathDirs = { "C:\\Tools", "C:\\Old" };
    m.files = { "C:\\Games\\Xenon\\StoneMath.dll", "C:\\Old\\StoneMath.dll", "C:\\Windows\\System32\\d3d11.dll", "C:\\Users\\ada\\Desktop\\fog.dll", "C:\\Tools\\fog.dll", "C:\\Old\\zlib.dll", "C:\\Games\\Xenon\\kernel32.dll" };
    m.knownDlls = { "kernel32.dll", "user32.dll" };
    return m;
}
TEST("application folder first") { CHECK_EQ(findDll(sample(), "StoneMath.dll"), std::string("C:\\Games\\Xenon\\StoneMath.dll")); }
TEST("system folder") { CHECK_EQ(findDll(sample(), "d3d11.dll"), std::string("C:\\Windows\\System32\\d3d11.dll")); }
TEST("current directory before PATH") { CHECK_EQ(findDll(sample(), "fog.dll"), std::string("C:\\Users\\ada\\Desktop\\fog.dll")); }
TEST("PATH last") { CHECK_EQ(findDll(sample(), "zlib.dll"), std::string("C:\\Old\\zlib.dll")); }
TEST("known DLLs ignore the app folder") { CHECK_EQ(findDll(sample(), "kernel32.dll"), std::string("C:\\Windows\\System32\\kernel32.dll")); }
TEST("already loaded wins") { Machine m = sample(); m.alreadyLoaded = { "C:\\Old\\StoneMath.dll" }; CHECK_EQ(findDll(m, "StoneMath.dll"), std::string("C:\\Old\\StoneMath.dll")); }
TEST("not found") { CHECK_EQ(findDll(sample(), "audio.dll"), std::string("")); }
TEST("a loaded module with a longer name does not count") { Machine m = sample(); m.alreadyLoaded = { "C:\\X\\notStoneMath.dll" }; CHECK_EQ(findDll(m, "StoneMath.dll"), std::string("C:\\Games\\Xenon\\StoneMath.dll")); }

